using System;using System.Linq;using System.Collections.Generic;using Mono.Cecil;using Mono.Cecil.Cil;using System.IO;
class Transplant {
 static ModuleDefinition target;static TypeDefinition Find(string n)=>target.Types.SelectMany(Flatten).FirstOrDefault(t=>t.FullName==n);static IEnumerable<TypeDefinition> Flatten(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var c in Flatten(n))yield return c;}
 static TypeReference Type(TypeReference t){if(t is ByReferenceType b)return new ByReferenceType(Type(b.ElementType));if(t is ArrayType a)return new ArrayType(Type(a.ElementType),a.Rank);if(t is GenericInstanceType g){var x=new GenericInstanceType(Type(g.ElementType));foreach(var arg in g.GenericArguments)x.GenericArguments.Add(Type(arg));return x;}var own=Find(t.FullName);return own??target.ImportReference(t);}
 static string Signature(TypeReference t)=>t is GenericParameter p?"!"+p.Type+":"+p.Position:t.FullName;
 static MethodReference Method(MethodReference m){if(m is GenericInstanceMethod g){var x=new GenericInstanceMethod(Method(g.ElementMethod));foreach(var arg in g.GenericArguments)x.GenericArguments.Add(Type(arg));return x;}if(m.DeclaringType is GenericInstanceType){var declaring=(GenericInstanceType)Type(m.DeclaringType);Func<TypeReference,TypeReference> contextual=t=>t is GenericParameter p&&p.Type==GenericParameterType.Type?declaring.ElementType.GenericParameters[p.Position]:Type(t);var reference=new MethodReference(m.Name,contextual(m.ReturnType),declaring){HasThis=m.HasThis,ExplicitThis=m.ExplicitThis,CallingConvention=m.CallingConvention};foreach(var parameter in m.Parameters)reference.Parameters.Add(new ParameterDefinition(contextual(parameter.ParameterType)));return reference;}var type=Find(m.DeclaringType.FullName);if(type!=null){var possibilities=type.Methods.Where(x=>x.Name==m.Name&&x.Parameters.Count==m.Parameters.Count&&x.GenericParameters.Count==m.GenericParameters.Count).ToArray();var found=possibilities.SingleOrDefault(x=>x.Parameters.Select(p=>Signature(p.ParameterType)).SequenceEqual(m.Parameters.Select(p=>Signature(p.ParameterType))));if(found==null)throw new Exception("Missing fixture method "+m.FullName);if(Signature(found.ReturnType)!=Signature(m.ReturnType))throw new Exception("Fixture return type mismatch "+m.FullName);return found;}if(m.DeclaringType.FullName.StartsWith("HutongGames."))throw new Exception("Unmapped native method "+m.FullName);return target.ImportReference(m);}
 static FieldReference Field(FieldReference f){var type=Find(f.DeclaringType.FullName);if(type!=null){var found=type.Fields.SingleOrDefault(x=>x.Name==f.Name);if(found==null||found.FieldType.FullName!=f.FieldType.FullName)throw new Exception("Missing fixture field "+f.FullName+" actual="+found?.FieldType.FullName);return found;}return target.ImportReference(f);}
 static void Copy(MethodDefinition from,MethodDefinition to){var b=new MethodBody(to){InitLocals=from.Body.InitLocals,MaxStackSize=from.Body.MaxStackSize};to.Body=b;foreach(var v in from.Body.Variables)b.Variables.Add(new VariableDefinition(Type(v.VariableType)));var map=new Dictionary<Instruction,Instruction>();foreach(var i in from.Body.Instructions){var n=Instruction.Create(OpCodes.Nop);n.OpCode=i.OpCode;b.Instructions.Add(n);map[i]=n;}foreach(var i in from.Body.Instructions){object o=i.Operand;if(o is Instruction j)o=map[j];else if(o is Instruction[] js)o=js.Select(x=>map[x]).ToArray();else if(o is TypeReference t)o=Type(t);else if(o is MethodReference m)o=Method(m);else if(o is FieldReference f)o=Field(f);else if(o is VariableDefinition v)o=b.Variables[v.Index];else if(o is ParameterDefinition p)o=to.Parameters[p.Index];map[i].Operand=o;}if(from.Body.ExceptionHandlers.Count!=0)throw new Exception("Unmodeled exception regions");if(!from.Body.Instructions.Select(x=>x.OpCode.Value).SequenceEqual(b.Instructions.Select(x=>x.OpCode.Value)))throw new Exception("Opcode mismatch");Console.WriteLine("TRANSPLANTED exact opcode/branch sequence "+from.FullName);}
 static void Clone(TypeDefinition parent,TypeDefinition[] originals){
 var copies=new Dictionary<TypeDefinition,TypeDefinition>();
 foreach(var t in originals){var c=new TypeDefinition(t.Namespace,t.Name,t.Attributes,Type(t.BaseType));parent.NestedTypes.Add(c);copies[t]=c;}
 foreach(var t in originals){var c=copies[t];foreach(var iface in t.Interfaces)c.Interfaces.Add(new InterfaceImplementation(Type(iface.InterfaceType)));foreach(var f in t.Fields)c.Fields.Add(new FieldDefinition(f.Name,f.Attributes,Type(f.FieldType)));foreach(var m in t.Methods){var n=new MethodDefinition(m.Name,m.Attributes,Type(m.ReturnType));foreach(var p in m.Parameters)n.Parameters.Add(new ParameterDefinition(p.Name,p.Attributes,Type(p.ParameterType)));c.Methods.Add(n);}}
 foreach(var t in originals)for(int i=0;i<t.Methods.Count;i++){var m=t.Methods[i];var n=copies[t].Methods[i];foreach(var ov in m.Overrides)n.Overrides.Add(Method(ov));Copy(m,n);}
 }
 static void Main(string[] args){using(var native=AssemblyDefinition.ReadAssembly(args[0]))using(var fixture=AssemblyDefinition.ReadAssembly(args[1])){target=fixture.MainModule;var soul=native.MainModule.GetType("SoulOrb");var iterator=soul.NestedTypes.Single(t=>t.Name.StartsWith("<Zoom>"));var copy=new TypeDefinition(iterator.Namespace,iterator.Name,iterator.Attributes,Type(iterator.BaseType));Find("SoulOrb").NestedTypes.Add(copy);
foreach(var iface in iterator.Interfaces)copy.Interfaces.Add(new InterfaceImplementation(Type(iface.InterfaceType)));
foreach(var f in iterator.Fields)copy.Fields.Add(new FieldDefinition(f.Name,f.Attributes,Type(f.FieldType)));
foreach(var m in iterator.Methods){var n=new MethodDefinition(m.Name,m.Attributes,Type(m.ReturnType));foreach(var p in m.Parameters)n.Parameters.Add(new ParameterDefinition(p.Name,p.Attributes,Type(p.ParameterType)));copy.Methods.Add(n);}
for(int i=0;i<iterator.Methods.Count;i++){var m=iterator.Methods[i];var n=copy.Methods[i];foreach(var ov in m.Overrides)n.Overrides.Add(Method(ov));Copy(m,n);}
var scuttler=native.MainModule.GetType("ScuttlerControl");Clone(Find("ScuttlerControl"),scuttler.NestedTypes.Where(t=>t.Name.StartsWith("<Heal>")||t.Name.Contains("DisplayClass43")).ToArray());
var selected=new Dictionary<string,string[]>{{"ScuttlerControl",new[]{"Hit","Heal"}},{"SoulOrb",new[]{"Awake","Start","OnEnable","OnDisable","Zoom","FireAtTarget","Update","FaceAngle","ProjectileSquash"}},{"HutongGames.PlayMaker.Actions.FlingObjectsFromGlobalPool",new[]{"OnEnter"}}};foreach(var e in selected)foreach(string name in e.Value){var type=native.MainModule.GetType(e.Key);var from=type.Methods.Single(x=>x.Name==name);var to=Find(e.Key).Methods.Single(x=>x.Name=="Native_"+name);Copy(from,to);}fixture.Write(args[2]);}}
}
